command:example.dev:code:
# Exportieren und mit vorherigem Backup vergleichen
$current = Export-ColorScriptMetadata -Path "./current-metadata.json" -IncludeFileInfo -PassThru
$previous = Get-Content "./previous-metadata.json" | ConvertFrom-Json
$new = $current | Where-Object { $_.Name -notin $previous.Name }
$removed = $previous | Where-Object { $_.Name -notin $current.Name }
Write-Host "Neue Skripte: $($new.Count) | Entfernte Skripte: $($removed.Count)"

dev:remarks.maml:para:
Ruft das aufgelöste Cache-Verzeichnis ab. `Cache.Path` bleibt die optionale, vom Benutzer konfigurierte Überschreibung;
`Cache.EffectivePath` zeigt das Verzeichnis an, das das Modul nach den Plattformstandards und tatsächlich verwendet
Umgebungsüberschreibungen werden angewendet.

command:example.dev:code:
$config = Get-ColorScriptConfiguration
if ($config.Cache.Path) {
    Write-Host "Benutzerdefinierter Cachepfad konfiguriert: $($config.Cache.Path)"
} else {
    Write-Host "Der Standard-Cachepfad wird verwendet"
}

Write-Host "Effektiver Cachepfad: $($config.Cache.EffectivePath)"

# Cache für gefilterte Skripte erstellen
Get-ColorScriptList -Tag Recommended -AsObject |
    ForEach-Object {
        New-ColorScriptCache -Name $_.Name -PassThru
    } |
    Format-Table Name, Status

# Finden Sie das erste Skript, das einem Muster entspricht, um es schnell anzuzeigen
$script = Get-ColorScriptList -Name "aurora-*" -AsObject | Select-Object -First 1
if ($script) {
    Show-ColorScript -Name $script.Name -PassThru
}

# Überprüfen Sie, ob alle referenzierten Skripte vorhanden sind, bevor Sie die Automatisierung ausführen
$requiredScripts = @("bars", "arch", "mandelbrot-zoom")
$available = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Name
$missing = $requiredScripts | Where-Object { $_ -notin $available }
if ($missing) {
    Write-Warning "Fehlende Skripte: $($missing -join ', ')"
} else {
    Write-Host "Alle erforderlichen Skripte sind verfügbar"
}

# Erstellen Sie mehrere Farbskripte für ein Projekt
$scriptNames = @("company-logo", "team-banner", "status-display")
foreach ($name in $scriptNames) {
    New-ColorScript -Name $name -Category "Corporate" -Tag "Custom" -OutputPath ".\src" | Out-Null
}
Write-Host "$($scriptNames.Count) Farbskriptvorlagen erstellt"

# Überprüfen Sie die Konventionen für Skriptnamen
$validName = "123-start"
$invalidNames = @("-invalid", "_underscore-only", "contains space")
foreach ($name in $invalidNames) {
    try {
        New-ColorScript -Name $name -OutputPath ./temp -WhatIf -ErrorAction Stop
    } catch {
        Write-Warning "Ungültiger Name '$name': $_"
    }
}

# Erstellen Sie mit Kategorie- und Tag-Validierung
$categories = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Category -Unique
if ("Retro" -in $categories) {
    New-ColorScript -Name "retro-party" -OutputPath ./ColorScripts-Enhanced/Scripts -Category "Artistic" -Tag "Fun","Social"
} else {
    Write-Warning "Die Kategorie Retro wurde nicht gefunden"
}

# Überprüfen Sie, ob das Zurücksetzen erfolgreich war
$config = Reset-ColorScriptConfiguration -PassThru
if ($null -eq $config.Cache.Path -and $config.Cache.EffectivePath) {
    Write-Host "Die Konfiguration wurde auf den Plattformstandard zurückgesetzt"
} else {
    Write-Host "Konfiguration zurückgesetzt; benutzerdefinierter Pfad wird verwendet: $($config.Cache.Path)"
}

# Erstellen Sie eine Diashow mit geometrischem Farbskripte
Get-ColorScriptList -Category Geometric -AsObject |
    ForEach-Object {
        Show-ColorScript -Name $_.Name
        Start-Sleep -Seconds 3
    }

# Beispiel für die Fehlerbehandlung
try {
    Show-ColorScript -Name "nonexistent-script" -ErrorAction Stop
} catch {
    Write-Warning "Skript nicht gefunden: $_"
    Show-ColorScript  # Ersatzweise eine zufällige Auswahl anzeigen
}

# Automatisierungsintegration erstellen
if ($env:CI) {
    Show-ColorScript -Name "Galaxy" -NoCache
} else {
    Show-ColorScript  # Zufallsanzeige zur interaktiven Verwendung
}

# Geplante Aufgabe für die Terminalbegrüßung
$scriptPath = "$(Get-Module ColorScripts-Enhanced).ModuleBase\Scripts\mandelbrot-zoom.ps1"
if (Test-Path $scriptPath) {
    & $scriptPath
} else {
    Show-ColorScript -Name mandelbrot-zoom
}
